#!/bin/zsh
# Generated by `lwm adapters`. Source this file from zsh when you want
# shell commands that expose the shared llm-workmem context.

export LWM_ROOT='/Users/ethan/Library/Mobile Documents/com~apple~CloudDocs/Downloads/LLM-WorkMem'

lwm-root() {
  printf '%s\n' "$LWM_ROOT"
}

lwm-open() {
  open "$LWM_ROOT/knowledge-digest.html"
}

lwm-status() {
  cd "$LWM_ROOT" && uv run --extra dev lwm audit "$LWM_ROOT" --eval-suite "$LWM_ROOT/wiki/eval-suite.txt"
}

lwm-refresh() {
  cd "$LWM_ROOT" && uv run --extra dev lwm watch "$LWM_ROOT" --eval-suite "$LWM_ROOT/wiki/eval-suite.txt"
}

lwm-context() {
  sed -n '1,220p' "$LWM_ROOT/llms.txt"
}
